#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <vector>

template <typename scalar_t>
__device__ inline float to_float_dev(scalar_t v) {
    return static_cast<float>(v);
}
template <>
__device__ inline float to_float_dev<c10::Half>(c10::Half v) {
    return __half2float(reinterpret_cast<__half&>(v));
}
template <>
__device__ inline float to_float_dev<c10::BFloat16>(c10::BFloat16 v) {
#if defined(__CUDA_ARCH__) && __CUDA_ARCH__ >= 800
    return __bfloat162float(reinterpret_cast<__nv_bfloat16&>(v));
#else
    return (float)v;
#endif
}

template <typename scalar_t>
__device__ inline scalar_t from_float_dev(float v) {
    return static_cast<scalar_t>(v);
}
template <>
__device__ inline c10::Half from_float_dev<c10::Half>(float v) {
    __half h = __float2half_rn(v);
    return reinterpret_cast<c10::Half&>(h);
}
template <>
__device__ inline c10::BFloat16 from_float_dev<c10::BFloat16>(float v) {
#if defined(__CUDA_ARCH__) && __CUDA_ARCH__ >= 800
    __nv_bfloat16 b = __float2bfloat16(v);
    return reinterpret_cast<c10::BFloat16&>(b);
#else
    return c10::BFloat16(v);
#endif
}

