    TORCH_CHECK(w.dim() == 1, "w must be 1D");
    TORCH_CHECK(x.size(1) == w.size(0), "shape mismatch");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(w.is_contiguous(), "w must be contiguous");

