    auto r = torch::empty({x.size(0)}, x.options().dtype(torch::kFloat));

    int N = (int)x.size(0);
    int D = (int)x.size(1);

    int threads = 256;
    if (D <= 128) threads = 128;
    else if (D <= 256) threads = 256;
